import numpy as np
lines = open('opt.xyz').read().split('\n')[2:]
els, xyz = [], []
for l in lines:
    if l.strip():
        p = l.split()
        els.append(p[0]); xyz.append([float(v) for v in p[1:4]])
xyz = np.array(xyz)
n = len(els)
iIn = els.index('In'); iB = els.index('B')
print('In idx', iIn, 'B idx', iB)
for i in range(n):
    if els[i] in ('In','B','S'):
        for j in range(n):
            if j==i: continue
            d = np.linalg.norm(xyz[i]-xyz[j])
            if d < 2.6 and els[j] not in ('H',):
                print(f'{els[i]}{i} - {els[j]}{j}  {d:.2f}')
        print()
# H on B?
for j in range(n):
    d = np.linalg.norm(xyz[iB]-xyz[j])
    if d < 1.6: print('B-H?', els[j], j, round(d,2))
